fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // Determine the length of the broadcasted outputs
    let out_len = m.max(n);

    // Since the problem guarantees non-empty inputs and compatibility
    // (either same length or one of them has length 1), we don't need
    // to handle other error cases.

    if m == n {
        // Same length: just clone both
        (a.clone(), b.clone())
    } else if m == 1 {
        // `a` is scalar: repeat its single value, copy `b` as is
        let repeated = vec![a[0]; out_len];
        (repeated, b.clone())
    } else {
        // `b` must have length 1: repeat its single value, copy `a` as is
        let repeated = vec![b[0]; out_len];
        (a.clone(), repeated)
    }
}

